import math
from functools import reduce

def lcm(a, b):
    return abs(a*b) // math.gcd(a, b)

def lcm_list(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

# Test n=4, check x_2 vs x_3
n = 4
k = 2
x_k = lcm_list(list(range(k, k + n)))
x_k_plus_1 = lcm_list(list(range(k + 1, k + 1 + n)))

print(f"n={n}, k={k}")
print(f"x_{k} = {x_k}")
print(f"x_{k+1} = {x_k_plus_1}")
if x_k == x_k_plus_1:
    print("x_k equals x_{k+1}")
